use crate::{FlipbookFrame, FlipbookPlayer};
use bevy::{
    camera::visibility::Visibility,
    ecs::{
        hierarchy::Children,
        observer::On,
        system::{Commands, Query},
    },
    gltf::GltfExtras,
    world_serialization::WorldInstanceReady,
};
use serde::Deserialize;

/// Add this as an observer when you are spawning a gltf generated by vox-to-gltf which contains flipbook animations.
/// Requires [`FlipbookPlugin`] to be installed.
///
/// ### Example
/// ```
/// use bevy::prelude::*;
/// use flipbook::{FlipbookPlugin, FlipbookPlayer, on_flipbook_ready};
///
/// fn main() {
///     App::default()
///         .add_plugins((DefaultPlugins, FlipbookPlugin))
///         .add_systems(Startup, spawn_scene)
/// #       .add_observer(assert_flipbook_added)
///         .run();
/// }
///
/// fn spawn_scene(
///     mut commands: Commands,
///     assets: Res<AssetServer>,
/// ) {
///     let handle = assets.load(GltfAssetLabel::Scene(0).from_asset("deer.glb"));
///     commands.spawn(
///         WorldAssetRoot(handle)
///     )
///     .observe(on_flipbook_ready);
///
/// }
///
/// # fn assert_flipbook_added(
/// #   _trigger: On<Add<FlipbookPlayer>>,
/// #   mut exit: MessageWriter<AppExit>,
/// # ) {
/// #   exit.write(AppExit::Success);
/// # }
/// ```
pub fn on_flipbook_ready(
    instance: On<WorldInstanceReady>,
    children: Query<&Children>,
    extras: Query<&GltfExtras>,
    mut visibility: Query<&mut Visibility>,
    mut commands: Commands,
) {
    for entity in children.iter_descendants(instance.entity) {
        let Ok(extras) = extras.get(entity) else {
            continue;
        };

        let Some(vox_bake) = parse_node_extras(&extras.value) else {
            continue;
        };

        if let Some(frame) = vox_bake.animation_frame {
            if let Ok(mut visibility) = visibility.get_mut(entity) {
                *visibility = if frame.initially_visible {
                    Visibility::Inherited
                } else {
                    Visibility::Hidden
                };
            }
            commands.entity(entity).insert(FlipbookFrame(frame.index));
        }

        if let Some(animation) = vox_bake.animation {
            commands
                .entity(entity)
                .insert(FlipbookPlayer::from_frame_count(animation.frame_count));
        }
    }
}

#[derive(Debug, Deserialize)]
struct NodeExtras {
    vox_bake: Option<VoxBakeExtras>,
}

#[derive(Debug, Deserialize)]
struct VoxBakeExtras {
    version: u32,
    animation: Option<AnimationExtras>,
    animation_frame: Option<AnimationFrameExtras>,
}

#[derive(Debug, Deserialize)]
struct AnimationExtras {
    frame_count: usize,
}

#[derive(Debug, Deserialize)]
struct AnimationFrameExtras {
    index: usize,
    initially_visible: bool,
}

fn parse_node_extras(value: &str) -> Option<VoxBakeExtras> {
    let metadata = serde_json::from_str::<NodeExtras>(value).ok()?;
    let vox_bake = metadata.vox_bake?;
    (vox_bake.version == 1).then_some(vox_bake)
}

#[cfg(test)]
mod tests {
    use std::time::{Duration, Instant};

    use super::parse_node_extras;
    use crate::{FlipbookPlayer, FlipbookPlugin, FlipbookSpeed, on_flipbook_ready};
    use bevy::{
        MinimalPlugins,
        animation::AnimationPlugin,
        app::App,
        asset::{AssetApp, AssetPlugin, AssetServer, Handle},
        ecs::{hierarchy::Children, name::Name, system::Commands},
        gltf::{GltfAssetLabel, GltfPlugin},
        image::Image,
        mesh::MeshPlugin,
        pbr::{MaterialPlugin, StandardMaterial},
        prelude::{Add, On, Visibility},
        time::TimeUpdateStrategy,
        world_serialization::{WorldAsset, WorldAssetRoot, WorldSerializationPlugin},
    };

    fn deer_nodes() -> Vec<(String, super::VoxBakeExtras, Option<bool>)> {
        let gltf = gltf::Gltf::from_slice(include_bytes!("../assets/deer.glb"))
            .expect("deer.glb should be valid glTF");
        gltf.document
            .nodes()
            .filter_map(|node| {
                let extras = node.extras().as_ref()?.get();
                let metadata = parse_node_extras(extras)?;
                let extension_visibility = node
                    .extension_value("KHR_node_visibility")
                    .and_then(|extension| extension.get("visible"))
                    .and_then(serde_json::Value::as_bool);
                Some((
                    node.name().unwrap_or_default().to_owned(),
                    metadata,
                    extension_visibility,
                ))
            })
            .collect()
    }

    #[test]
    fn deserializes_deer_animation_parent() {
        let nodes = deer_nodes();
        let parents = nodes
            .iter()
            .filter_map(|(name, metadata, _)| {
                metadata
                    .animation
                    .as_ref()
                    .map(|animation| (name, animation.frame_count))
            })
            .collect::<Vec<_>>();

        assert_eq!(parents.len(), 1);
        assert_eq!(parents[0].0.as_str(), "deer");
        assert_eq!(parents[0].1, 4);
    }

    #[test]
    fn deserializes_deer_frames_in_order_with_one_initially_visible() {
        let nodes = deer_nodes();
        let mut frames = nodes
            .iter()
            .filter_map(|(name, metadata, extension_visibility)| {
                metadata
                    .animation_frame
                    .as_ref()
                    .map(|frame| (name, frame, extension_visibility))
            })
            .collect::<Vec<_>>();
        frames.sort_by_key(|(_, frame, _)| frame.index);

        assert_eq!(frames.len(), 4);
        for (expected_index, (name, frame, extension_visibility)) in frames.iter().enumerate() {
            assert_eq!(frame.index, expected_index);
            assert_eq!(name.as_str(), format!("deer-{:03}", expected_index + 1));
            assert_eq!(frame.initially_visible, expected_index == 0);
            assert_eq!(**extension_visibility, Some(frame.initially_visible));
        }
    }

    #[test]
    fn ignores_unrelated_malformed_and_unsupported_extras() {
        assert!(parse_node_extras(r#"{"other": {}}"#).is_none());
        assert!(parse_node_extras("not JSON").is_none());
        assert!(
            parse_node_extras(r#"{"vox_bake":{"version":2,"animation":{"frame_count":4}}}"#)
                .is_none()
        );
    }

    #[test]
    fn spawn_play_animation() {
        let mut app = App::new();
        app.add_plugins((
            MinimalPlugins,
            AssetPlugin {
                file_path: format!("{}/assets", env!("CARGO_MANIFEST_DIR")),
                ..Default::default()
            },
            WorldSerializationPlugin::default(),
            MeshPlugin,
            MaterialPlugin::<StandardMaterial>::default(),
            AnimationPlugin,
            GltfPlugin::default(),
            FlipbookPlugin,
        ))
        .init_asset::<Image>();
        app.finish();
        app.cleanup();

        let assets = app.world().resource::<AssetServer>().clone();
        let scene_handle: Handle<WorldAsset> =
            assets.load(GltfAssetLabel::Scene(0).from_asset("deer.glb"));
        let deadline = Instant::now() + Duration::from_secs(5);
        while !assets.is_loaded_with_dependencies(&scene_handle) {
            assert!(
                Instant::now() < deadline,
                "deer.glb scene should load within five seconds"
            );
            app.update();
            std::thread::yield_now();
        }
        // Use an observer to give the player a very fast frame rate so each
        // subsequent app update advances the animation.
        app.add_observer(
            move |trigger: On<Add<FlipbookPlayer>>, mut commands: Commands| {
                commands
                    .entity(trigger.entity)
                    .insert(FlipbookSpeed(Duration::from_millis(1)));
            },
        );
        app.insert_resource(TimeUpdateStrategy::ManualDuration(Duration::from_millis(1)));
        let _scene_root = app
            .world_mut()
            .spawn(WorldAssetRoot(scene_handle))
            .observe(on_flipbook_ready)
            .id();
        app.update();
        app.update();
        let player = app
            .world()
            .iter_entities()
            .find(|entity| entity.contains::<FlipbookPlayer>())
            .map(|entity| entity.id())
            .expect("flipbook player");
        let name = app.world().get::<Name>(player).expect("node is named");
        assert!(
            name.as_str() == "deer",
            "FlipbookPlayer added to the unsuffixed animated-model parent"
        );
        let frames = app.world().get::<Children>(player).expect("frames");
        assert_eq!(frames.len(), 4);
        let first_frame_visibility = app
            .world()
            .get::<Visibility>(frames[0])
            .expect("Visibility of first frame");
        assert_eq!(
            first_frame_visibility,
            Visibility::Hidden,
            "Frame 0 invisible"
        );
        let second_frame_visibility = app
            .world()
            .get::<Visibility>(frames[1])
            .expect("Visibility of second frame");
        assert_eq!(
            second_frame_visibility,
            Visibility::Inherited,
            "Frame 1 is showing"
        );
    }
}
